import unittest

from solution import render_observation


class RenderObservationTests(unittest.TestCase):
    def test_exact_rendering_trimming_and_conversion(self):
        observation = {
            "temperature_c": 21.24,
            "summary": "  Light rain  ",
            "wind_mps": 2.0,
        }
        snapshot = dict(observation)
        rendered = render_observation("  Bengaluru  ", observation)
        self.assertEqual(
            rendered,
            "Place: Bengaluru\n"
            "Conditions: Light rain\n"
            "Temperature: 21.2 C; Wind: 7.2 km/h",
        )
        self.assertEqual(observation, snapshot)

    def test_negative_values_are_permitted(self):
        self.assertEqual(
            render_observation(
                "Station", {"temperature_c": -3, "summary": "Clear", "wind_mps": -1}
            ),
            "Place: Station\n"
            "Conditions: Clear\n"
            "Temperature: -3.0 C; Wind: -3.6 km/h",
        )

    def test_place_validation(self):
        for place in (None, 12):
            with self.subTest(place=place), self.assertRaises(TypeError):
                render_observation(
                    place, {"temperature_c": 1, "summary": "x", "wind_mps": 1}
                )
        for place in ("", " \t\n "):
            with self.subTest(place=place), self.assertRaises(ValueError):
                render_observation(
                    place, {"temperature_c": 1, "summary": "x", "wind_mps": 1}
                )

    def test_mapping_shape_and_summary_validation(self):
        valid = {"temperature_c": 1, "summary": "x", "wind_mps": 1}
        with self.assertRaises(TypeError):
            render_observation("p", [])
        with self.assertRaises(ValueError):
            render_observation("p", {"temperature_c": 1, "summary": "x"})
        with self.assertRaises(ValueError):
            render_observation("p", dict(valid, extra=1))
        with self.assertRaises(TypeError):
            render_observation("p", dict(valid, summary=4))
        with self.assertRaises(ValueError):
            render_observation("p", dict(valid, summary="   "))

    def test_numeric_validation(self):
        valid = {"temperature_c": 1, "summary": "x", "wind_mps": 1}
        for key, value, error in [
            ("temperature_c", True, TypeError),
            ("wind_mps", "2", TypeError),
            ("temperature_c", float("nan"), ValueError),
            ("wind_mps", float("inf"), ValueError),
            ("wind_mps", float("-inf"), ValueError),
        ]:
            observation = dict(valid)
            observation[key] = value
            with self.subTest(key=key, value=value), self.assertRaises(error):
                render_observation("p", observation)


if __name__ == "__main__":
    unittest.main()

